program:
root = Col([heading, sampleNote, topBar, scene])
$step = 0
$wrong = 0
$feedback = ""
$isCorrect = false
heading = Col([Title("酒店入住练习 · 前台角色", "xl"), Text("我会一句一句扮演前台。你从选项中选择回复，说错了会提示原因，说对了才进入下一句。", "sm", "muted")], 2)
sampleNote = Caption("示例对话，仅用于日语练习，不构成真实预订或入住结果。")
topBar = Row([progress, Spacer(), reset], 3)
progress = Text("第 " + @Clamp($step + 1, 0, @Count(script)) + " 句 / 共 " + @Count(script) + " 句 · 说错 " + $wrong + " 次", "sm", "muted")
reset = Button("重新开始", resetAction, "ghost", null, "sm", "rotate-ccw")
resetAction = Action([@Reset($step, $wrong, $feedback, $isCorrect)])
scene = $step < @Count(script) ? currentScene : doneScene
currentScene = Card([Row([Badge("前台", "purple"), Badge("第 " + ($step + 1) + " 句", "info")], 1, null, null, true), Text(turn.front, "lg", "ink", "medium"), Text(turn.romaji, "sm", "muted"), Text(turn.zh, "sm", "faint"), Divider(), Text("请选择你的回复", "sm", "muted"), choices, feedbackArea], "soft", 4, 3)
choices = Col(@Each(turn.options, "opt", Button(opt.label, opt.correct ? Action([@Set($isCorrect, true), @Set($feedback, opt.explain), @Set($step, $step + 1)]) : Action([@Set($isCorrect, false), @Set($feedback, opt.explain), @Set($wrong, $wrong + 1)]), "outline", null, "sm", null, false, true)), 2)
feedbackArea = $feedback != "" ? Row([Icon($isCorrect ? "check-circle" : "alert-circle", "sm", $isCorrect ? "success" : "danger"), Text($feedback, "sm", $isCorrect ? "success" : "danger")], 2) : null
doneScene = Card([Title("练习完成", "md"), Text("你已完成 " + @Count(script) + " 句入住对话，共说错 " + $wrong + " 次。可以重新开始，或复习上面的表达。", "sm"), Button("重新开始", resetAction, "solid", null, "sm", "rotate-ccw")], "soft", 4, 3)
safeStep = @Clamp($step, 0, @Count(script) - 1)
turn = script[safeStep]
script = [
  {
    front: "いらっしゃいませ。ご予約はありますか？",
    romaji: "Irasshaimase. Go-yoyaku wa arimasu ka?",
    zh: "欢迎光临。请问您有预订吗？",
    options: [
      {label: "はい、予約しています。田中です。", correct: true, explain: "正确：先确认有预订，并报出姓名。已进入下一句。"},
      {label: "いいえ、ありません。でも泊まれますか？", correct: false, explain: "如果你其实有预订，应说「はい、予約しています」。再试一次。"},
      {label: "こんにちは。今日は暑いですね。", correct: false, explain: "寒暄可以，但前台在确认预订，先回答有没有预订。"}
    ]
  },
  {
    front: "お名前を確認させていただけますか？パスポートをお見せください。",
    romaji: "Onamae o kakunin sasete itadakemasu ka? Pasupōto o misete kudasai.",
    zh: "请让我确认您的姓名，并出示护照。",
    options: [
      {label: "はい、どうぞ。こちらがパスポートです。", correct: true, explain: "正确：配合出示护照，办理入住更顺利。已进入下一句。"},
      {label: "パスポートは家に忘れました。", correct: false, explain: "办理入住通常需要护照，这句话会无法继续。正确的做法是出示护照，或至少说明情况并寻求帮助。"},
      {label: "私の名前は秘密です。", correct: false, explain: "前台需要核对预订姓名，不能说保密。正确做法是配合出示护照。"}
    ]
  },
  {
    front: "ご予約はシングルルーム二泊、朝食付きで承っております。お間違いないですか？",
    romaji: "Go-yoyaku wa shinguru rūmu nihaku, chōshoku-tsuki de uketamawatte orimasu. Omachigai nai desu ka?",
    zh: "您的预订是单人间两晚，含早餐。请问对吗？",
    options: [
      {label: "はい、それで大丈夫です。", correct: true, explain: "正确：确认预订内容即可。已进入下一句。"},
      {label: "いいえ、朝食はいりません。", correct: false, explain: "如果确实想取消早餐可以提出，但当前是在确认预订内容。先确认正确，再提变更更自然。"},
      {label: "私は王様です。", correct: false, explain: "这句话与确认预订无关，无法办理入住。"}
    ]
  },
  {
    front: "お支払いは、ご到着時にカードでお願いしております。カードをお預かりしてもよろしいですか？",
    romaji: "O-shiharai wa, go-tōchaku-ji ni kādo de onegai shite orimasu. Kādo o oazukari shite mo yoroshii desu ka?",
    zh: "房费需在到店时刷卡。可以先收一下您的信用卡吗？",
    options: [
      {label: "はい、どうぞ。このカードでお願いします。", correct: true, explain: "正确：配合支付即可。已进入下一句。"},
      {label: "カードはありません。現金もありません。", correct: false, explain: "若确实没有支付方式要说明，但当前先练习配合支付。"},
      {label: "お金はあとで払います。", correct: false, explain: "到店付款通常需要现在提供卡或押金，不能只说以后付。"}
    ]
  },
  {
    front: "こちらがお部屋のカードキーです。8階の802号室です。朝食は7時から10時まで、2階のレストランでご利用いただけます。",
    romaji: "Kochira ga o-heya no kādo kī desu. Hakkai no happyaku-ni-gōshitsu desu. Chōshoku wa shichi-ji kara jū-ji made, ni-kai no resutoran de go-riyō itadakemasu.",
    zh: "这是您的房卡。房间在8楼802。早餐7点到10点，在2楼餐厅使用。",
    options: [
      {label: "ありがとうございます。朝食会場は2階ですね。", correct: true, explain: "正确：收下房卡并确认关键信息。已进入下一句。"},
      {label: "8階ですか？私は高い所が苦手です。", correct: false, explain: "可以表达需求，但当前先确认房间和早餐信息更合适。"},
      {label: "カードはいりません。", correct: false, explain: "房卡是进入房间必需，不能拒绝；正确做法是收下并道谢。"}
    ]
  },
  {
    front: "エレベーターはあちらです。ご不明な点があれば、いつでもフロントまでお申し付けください。ごゆっくりどうぞ。",
    romaji: "Erebētā wa achira desu. Go-fumei na ten ga areba, itsu demo furonto made mōshitsuke kudasai. Goyukkuri dōzo.",
    zh: "电梯在那边。如有任何不清楚的地方，请随时联系前台。祝您入住愉快。",
    options: [
      {label: "ありがとうございます。", correct: true, explain: "正确：道谢并结束入住对话。练习完成。"},
      {label: "何も聞きたくありません。", correct: false, explain: "这句不礼貌。更自然的是道谢，如「ありがとうございます」。"},
      {label: "バイバイ。", correct: false, explain: "对前台说「バイバイ」太随意，用「ありがとうございます」更合适。"}
    ]
  }
]
